ar-mini{width:35px;height:35px;border-radius:11px;border:1px solid var(--line);background:rgba(18,26,50,.72);font-size:16px;color:#c2ccee;display:grid;place-items:center}.icon-btn:hover{color:white;border-color:#76dfff88}.avatar-mini{border-radius:50%;color:#96f0ff;background:linear-gradient(140deg,#4d568b,#252b54);box-shadow:0 0 18px #76bfff33}.hud{position:fixed;inset:76px 0 0;z-index:2;pointer-events:none}.glass{background:linear-gradient(145deg,rgba(17,25,48,.85),rgba(9,15,32,.78));border:1px solid rgba(165,184,255,.14);box-shadow:0 16px 55px rgba(0,0,0,.24),inset 0 1px rgba(255,255,255,.035);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}.left-panel{position:absolute;left:34px;top:32px;width:286px;padding:20px 19px 16px;border-radius:17px;pointer-events:auto}.section-label{font:700 9px 'Space Grotesk';letter-spacing:1.45px;color:#9da9c9}.left-panel>.section-label{display:flex;align-items:center;white-space:nowrap}.left-panel .live-dot{width:5px;height:5px;margin-right:7px}.season{margin-left:auto;font-size:7px;color:#7884a5;letter-spacing:.8px}.power-row{display:flex;align-items:center;justify-content:space-between;margin-top:22px}.power-row small,.stat-card small,.aura-stats small{display:block;color:#8590ae;font-size:8px;font-weight:700;letter-spacing:1.2px;margin-bottom:4px}.power-row strong{font:700 31px 'Space Grotesk';letter-spacing:-1px;text-shadow:0 0 24px #73ddff44}.power-glyph{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;font-size:27px;color:#88e8ff;background:linear-gradient(145deg,#283f66,#222444);border:1px solid #6cdaff38;box-shadow:0 0 25px #67d8ff18}.xp-track{height:3px;margin-top:13px;background:#28324d;border-radius:4px;overflow:hidden}.xp-track div{height:100%;width:0;background:linear-gradient(90deg,#69d8ff,#aa91ff);box-shadow:0 0 9px #6cdbff;transition:width .3s}.xp-meta{display:flex;justify-content:space-between;font-size:8px;color:#808cac;margin-top:7px;letter-spacing:.5px}.stat-grid{display:gri