d-template-columns:1fr 1fr;padding:12px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.aura-stats b{font:700 15px 'Space Grotesk';color:#eff1ff}.aura-stats b i{font-size:10px;color:#8792ae;font-style:normal}.outline-btn{height:37px;width:100%;margin-top:13px;border:1px solid rgba(166,187,255,.2);background:rgba(62,74,112,.24);border-radius:9px;text-align:left;padding:0 11px;color:#ced6f0;font:700 8px 'Space Grotesk';letter-spacing:.8px;transition:.2s}.outline-btn:hover{border-color:#80dcff77;background:#72dfff14}.outline-btn span{float:right;color:#9de8ff;font-size:13px}.quests-card{margin-top:12px;padding:16px 17px}.quest-reset{font:600 7px 'Space Grotesk';color:#7e8ba9;letter-spacing:.4px}.quest{display:flex;align-items:center;gap:10px;margin-top:15px}.quest-icon{width:28px;height:28px;display:grid;place-items:center;border-radius:9px;background:#9c85ff1c;color:#c2adff}.quest-copy{flex:1}.quest-copy b{font-size:9px;display:block}.quest-copy small{color:#8792ae;font-size:8px;display:block;margin-top:3px}.quest>strong{font:600 8px 'Space Grotesk';color:#b4bfd8}.quest-bar{height:3px;background:#303958;border-radius:4px;margin-top:7px}.quest-bar i{display:block;height:100%;width:0;background:#9d89ff;border-radius:4px}.quest-reward{margin:14px 0 0 38px;color:#71809e;font:700 7px 'Space Grotesk';letter-spacing:.8px}.quest-reward b{color:#ffd58b;margin-left:6px;font-size:9px}.bottom-center{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);white-space:nowrap}.world-hint{font:700 8px 'Space Grotesk';letter-spacing:1px;color:#9aa7c2;padding:10px 16px;border:1px solid rgba(172,187,255,.1);border-radius:30px;background:rgba(11,17,35,.55);backdrop-filter:blur(8px)}.world-hint span{color:#d8eaff}.world-hint i{font-style:normal;color:#62718f;margin:0 8px}.mobile-controls{display:none}.toast{position:absolute;top:25px;left:50%;transform:translate(-50%,-20px);padding:11px 18px;background:rgba(19,31,57,.95);border:1px solid #7adfff55;border-