* {
box-sizing:border-box}
 :root {
--ink:#f3f5ff;--muted:#8790aa;--cyan:#71e6ff;--violet:#a88bff;--panel:rgba(13,19,39,.79);--line:rgba(154,178,255,.13)}
html,body {
margin:0;width:100%;height:100%;overflow:hidden;background:#080d1b;color:var(--ink);font-family:'DM Sans',sans-serif}
button {
font:inherit;color:inherit;cursor:pointer}
#game {
position:fixed;inset:0;background:radial-gradient(ellipse at 50% 45%,#202952 0,#10172d 38%,#080d1a 80%)}
#game canvas {
display:block;width:100%;height:100%;touch-action:none}
.vignette {
position:fixed;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,8,19,.52),transparent 22%,transparent 66%,rgba(5,9,20,.36)),radial-gradient(ellipse at center,transparent 35%,rgba(5,8,20,.32) 100%)}
.topbar {
position:fixed;z-index:3;top:0;left:0;right:0;height:76px;padding:0 36px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(175,190,255,.08);background:linear-gradient(180deg,rgba(7,11,24,.87),rgba(7,11,24,.38))}
.brand {
display:flex;align-items:center;gap:11px;width:240px}
.brand-mark {
width:37px;height:37px;border:1px solid rgba(117,227,255,.55);border-radius:12px;display:grid;place-items:center;color:#8becff;background:linear-gradient(145deg,rgba(74,203,255,.2),rgba(132,106,255,.12));font-size:22px;box-shadow:0 0 24px #48baff20}
.brand b {
font:700 19px 'Space Grotesk';letter-spacing:1px}
.brand b span {
color:#77deff}
.brand small {
display:block;font-size:8px;letter-spacing:2.4px;color:#8591b4;margin-top:1px}
.top-center {
position:absolute;left:50%;transform:translateX(-50%)}
.realm-pill {
font:700 9px 'Space Grotesk';letter-spacing:1.55px;color:#c3cae4;padding:10px 15px;border:1px solid rgba(172,187,255,.13);background:rgba(14,20,40,.6);border-radius:30px}
.realm-pill i,.live-dot {
display:inline-block;width:6px;height:6px;border-radius:50%;background:#76e6d0;box-shadow:0 0 9px #76e6d0;margin-right:8px}
.realm-pill span {
color:#7a87aa;margin-left:10px}
.top-actions {
display:flex;align-items:center;gap:12px}
.icon-btn,.avatar-mini {
width:35px;height:35px;border-radius:11px;border:1px solid var(--line);background:rgba(18,26,50,.72);font-size:16px;color:#c2ccee;display:grid;place-items:center}
.icon-btn:hover {
color:white;border-color:#76dfff88}
.avatar-mini {
border-radius:50%;color:#96f0ff;background:linear-gradient(140deg,#4d568b,#252b54);box-shadow:0 0 18px #76bfff33}
.hud {
position:fixed;inset:76px 0 0;z-index:2;pointer-events:none}
.glass {
background:linear-gradient(145deg,rgba(17,25,48,.85),rgba(9,15,32,.78));border:1px solid rgba(165,184,255,.14);box-shadow:0 16px 55px rgba(0,0,0,.24),inset 0 1px rgba(255,255,255,.035);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}
.left-panel {
position:absolute;left:34px;top:32px;width:286px;padding:20px 19px 16px;border-radius:17px;pointer-events:auto}
.section-label {
font:700 9px 'Space Grotesk';letter-spacing:1.45px;color:#9da9c9}
.left-panel>.section-label {
display:flex;align-items:center;white-space:nowrap}
.left-panel .live-dot {
width:5px;height:5px;margin-right:7px}
.season {
margin-left:auto;font-size:7px;color:#7884a5;letter-spacing:.8px}
.power-row {
display:flex;align-items:center;justify-content:space-between;margin-top:22px}
.power-row small,.stat-card small,.aura-stats small {
