function auraStyle(id){return ['orbit','petal','crystal','wing','snake','galaxy','sunray','storm','volcano','throne'][Math.floor(id/3)%10]}
function makeAura(id){
 if(auraGroup){player.remove(auraGroup);auraGroup.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material.dispose()}})}
