 const ringMat=new THREE.MeshBasicMaterial({color:a.c,transparent:true,opacity:.43,side:THREE.DoubleSide});
 for(let i=0;i<3;i++){const r=new THREE.Mesh(new THREE.TorusGeometry(.78+i*.17,.012+(i===1?.006:0),6,72),ringMat.clone());r.position.y=.45+i*.58;r.rotation.x=Math.PI/2+(i-1)*.52;r.rotation.z=i*.8;root.add(r);rings.push(r)}
 const orbGeo=[new THREE.OctahedronGeometry(.13,0),new THREE.IcosahedronGeometry(.12,1),new THREE.TetrahedronGeometry(.15),new THREE.TorusGeometry(.13,.035,6,12)];
 const orbMat=new THREE.MeshStandardMaterial({color:a.c,emissive:a.c,emissiveIntensity:1.6,metalness:.2,roughness:.3});
 const count=style==='wing'?6:style==='sunray'?12:8;
 for(let i=0;i<count;i++){const mesh=new THREE.Mesh(orbGeo[(id+i)%orbGeo.length],orbMat.clone());const phase=i/count*Math.PI*2;const r=style==='wing'?.7:.83+(i%3)*.16;const y=.35+(i%4)*.52;mesh.position.set(Math.cos(phase)*r,y,Math.sin(phase)*r);mesh.scale.setScalar(style==='sunray'?.72:1);root.add(mesh);orbiters.push({mesh,phase,r,y,speed:.42+(i%4)*.09,kind:style==='wing'?'wing':style==='petal'?'petal':style==='snake'?'snake':style==='galaxy'?'galaxy':style==='sunray'?'sunray':'orb',offset:i})}
 if(['storm','volcano','throne','zenith'].includes(style))for(let i=0;i<6;i++){const b=new THREE.Mesh(new THREE.CylinderGeometry(.008,.045,2.5,5),new THREE.MeshBasicMaterial({color:i%2?a.c:a.s,transparent:true,opacity:.2}));b.position.set(Math.cos(i*Math.PI/3)*1.1,1.35,Math.sin(i*Math.PI/3)*1.1);root.add(b);beams.push(b)}
 const n=style==='galaxy'?180:100,positions=new Float32Array(n*3),vel=[];for(let i=0;i<n;i++){positions[i*3]=(Math.random()-.5)*1.8;positions[i*3+1]=Math.random()*3;positions[i*3+2]=(Math.random()-.5)*1.8;vel.push(.35+Math.random()*.8)}const pg=new THREE.BufferGeometry();pg.setAttribute('position',new THREE.BufferAttribute(positions,3));const particles=new THREE.Points(pg,new THREE.PointsMaterial({color:a.s,size:.045,transparent:true,opacity:.78,depthWrite:false,blending:THREE.AdditiveBlending}));root.add(particles);player.add(root);auraGroup=root;root.userData={rings,orbiters,particles,vel,glow,beams,style};
}
function checkUnlocks(){let changed=false;AURAS.forEach((a,i)=>{if(save.total>=a.req&&!save.unlocked.includes(i)){save.unlocked.push(i);changed=true;showToast(`Nova aura descoberta: ${a.name}!`)}});if(changed){save.unlocked.sort((a,b)=>a-b);renderCollection()}}
