.stat-icon.cyan{color:#73e4ff;background:#59dfff19}
.stat-icon.gold{color:#ffd78a;background:#ffc75a19}
.stat-card small{font-size:7px;margin:0 0 3px}
.stat-card b{font:700 13px 'Space Grotesk'}
.energy-header{display:flex;justify-content:space-between;margin-top:19px;color:#8995b2;font:700 8px 'Space Grotesk';letter-spacing:.85px}
.energy-header b{color:#d5dcf4;font-size:9px;letter-spacing:.2px}
.energy-track{height:7px;border-radius:5px;background:#27314d;margin-top:8px;overflow:hidden;position:relative}
.energy-track div{height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#54bfff,#a78cff);box-shadow:0 0 12px #61cfff88;transition:width .25s}
.energy-track span{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 24%,rgba(10,15,31,.6) 25% 26%)}
.rate-line{display:flex;justify-content:space-between;align-items:center;margin-top:12px;color:#7f8ba9;font:700 8px 'Space Grotesk';letter-spacing:.7px}
.rate-line b{color:#8ce5ff;font-size:11px;letter-spacing:0}
.rate-line em{font-style:normal;color:#d9b8ff}
.train-btn{width:100%;height:58px;margin-top:16px;display:flex;align-items:center;text-align:left;padding:0 12px;border:1px solid rgba(106,219,255,.45);border-radius:11px;background:linear-gradient(105deg,rgba(42,112,150,.75),rgba(83,71,143,.72));box-shadow:0 5px 25px #48cfff1c,inset 0 1px #ffffff18;transition:.18s;position:relative;overflow:hidden}
.train-btn:hover{filter:brightness(1.16);transform:translateY(-1px)}
.train-btn:active{transform:scale(.98)}
.train-icon{font-size:23px;margin-right:11px;color:#bcf5ff;text-shadow:0 0 12px #81eaff}
.train-btn>span:nth-child(2){font:700 10px 'Space Grotesk';letter-spacing:.7px}
.train-btn small{display:block;color:#b9c9e8;font-size:7px;letter-spacing:.8px;margin-top:4px}
.train-btn kbd{margin-left:auto;font:700 11px 'Space Grotesk';color:white;background:#ffffff1a;border:1px solid #ffffff24;border-radius:6px;padding:6px}
.train-btn kbd i{font-style:normal;color:#b3f3ff}
.auto-row{display:flex;align-items:center;margin-top:14px;gap:9px}
.auto-icon{width:29px;height:29px;display:grid;place-items:center;border-radius:9px;color:#c7a6ff;background:#a278ff1e;font-size:17px}
.auto-row b{display:block;font-size:9px;color:#d7def3}
.auto-row small{display:block;margin-top:3px;font-size:8px;color:#7c89a7}
.switch{margin-left:auto;width:31px;height:17px;border-radius:20px;border:1px solid #475273;background:#252e49;position:relative;padding:0}
.switch:after{content:'';position:absolute;left:2px;top:2px;width:11px;height:11px;border-radius:50%;background:#7d89a9;transition:.2s}
.switch.on{background:#45a9ca;border-color:#7ce6ff}
.switch.on:after{left:16px;background:#e6fbff;box-shadow:0 0 8px #8df1ff}
.switch:disabled{opacity:.42;cursor:not-allowed}
.right-panel{position:absolute;right:34px;top:32px;width:278px;pointer-events:auto}
.aura-card,.quests-card{border-radius:17px;padding:18px}
.aura-card-top,.quest-heading{display:flex;align-items:center;justify-content:space-between}
.rarity-badge{border:1px solid #8ce2ff4a;color:#a6eaff;background:#60d7ff13;border-radius:20px;padding:5px 8px;font:700 7px 'Space Grotesk';letter-spacing:1px}
.equipped-info{display:flex;gap:12px;align-items:center;margin:20px 0 17px}
.aura-emblem{width:50px;height:50px;flex-shrink:0;display:grid;place-items:center;border-radius:15px;font-size:26px;color:#a8f3ff;background:radial-gradient(circle at 35% 25%,#478caa66,#47407266 80%);border:1px solid #74ddff46;box-shadow:0 0 27px #7ceaff22,inset 0 0 18px #87dbff13}
