.outline-btn{height:37px;width:100%;margin-top:13px;border:1px solid rgba(166,187,255,.2);background:rgba(62,74,112,.24);border-radius:9px;text-align:left;padding:0 11px;color:#ced6f0;font:700 8px 'Space Grotesk';letter-spacing:.8px;transition:.2s}
