.toast.show{opacity:1;transform:translate(-50%,0)}
.modal-backdrop{position:fixed;z-index:10;inset:0;display:none;align-items:center;justify-content:center;padding:20px;background:#050914bb;backdrop-filter:blur(8px);pointer-events:auto}
