import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json')
const { chromium } = require('playwright')
const cfg = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'))
const browser = await chromium.launch({ ...cfg.browser.launchOptions, timeout: 30000 })
const page = await browser.newPage({ viewport: { width: 390, height: 844 } })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.addInitScript(() => localStorage.setItem('auraInfinitySave', JSON.stringify({energy:0,essence:100,total:0,level:1,xp:0,trained:0,unlocked:[0],equipped:0,auto:false,music:false,volume:24,quality:'high',upgradeRank:0,questProgress:24,questCycle:0})))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.locator('#trainBtn').click()
const progress = await page.locator('#questCount').textContent()
await page.locator('#questClaim').click()
const claimed = JSON.parse(await page.evaluate(() => localStorage.getItem('auraInfinitySave')))
await page.locator('#forgeBtn').click()
const forgeReady = await page.locator('#forgeBuy').isEnabled()
await page.locator('#forgeBuy').click()
const upgraded = JSON.parse(await page.evaluate(() => localStorage.getItem('auraInfinitySave')))
await page.locator('#settingsBtn').click()
const volume = page.locator('#musicVolume')
await volume.fill('0')
const zeroMuted = await page.locator('#audioToggle').getAttribute('aria-pressed')
await volume.fill('35')
const stillMuted = await page.locator('#audioToggle').getAttribute('aria-pressed')
await page.locator('#audioToggle').click()
const active = await page.locator('#audioToggle').getAttribute('aria-pressed')
const canvas = await page.locator('#game canvas').count()
const bodyOverflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth)
console.log(JSON.stringify({progress, claimedEssence:claimed.essence, forgeReady, upgradeRank:upgraded.upgradeRank, postUpgradeEssence:upgraded.essence, zeroMuted, stillMuted, active, canvas, bodyOverflow, errors}, null, 2))
await browser.close()

